package com.clinicbooking.medicalrecord.infrastructure.in.rest;
import com.clinicbooking.medicalrecord.application.port.in.MedicalRecordUseCase; import com.clinicbooking.medicalrecord.domain.*; import org.junit.jupiter.api.Test; import org.springframework.test.web.servlet.MockMvc; import org.springframework.test.web.servlet.setup.MockMvcBuilders; import java.time.LocalDateTime; import java.util.*; import static org.mockito.Mockito.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class MedicalRecordControllerTest {
 @Test void triageEndpointReturnsClassification() throws Exception {MedicalRecordUseCase use=mock(MedicalRecordUseCase.class);UUID p=UUID.randomUUID(),d=UUID.randomUUID();var m=new MedicalRecord(null,p,d,120,80,37,80,98,LocalDateTime.now());when(use.triage(any(),any(),anyInt(),anyInt(),anyDouble(),anyInt(),anyInt(),anyList())).thenReturn(m);MockMvc mvc=MockMvcBuilders.standaloneSetup(new MedicalRecordController(use)).build();mvc.perform(post("/api/v1/medical-records/triage-assessment").contentType("application/json").content("{\"patientId\":\""+p+"\",\"doctorId\":\""+d+"\",\"systolic\":120,\"diastolic\":80,\"temperature\":37,\"heartRate\":80,\"spo2\":98,\"allergies\":[]}" )).andExpect(status().isOk()).andExpect(jsonPath("$.triage").value("V"));}
 @Test void prescriptionAndCloseRoutesDelegate() throws Exception {MedicalRecordUseCase use=mock(MedicalRecordUseCase.class);UUID id=UUID.randomUUID();var m=new MedicalRecord(id,UUID.randomUUID(),UUID.randomUUID(),120,80,37,80,98,LocalDateTime.now());when(use.prescribe(eq(id),eq("Rx"))).thenReturn(m);when(use.close(eq(id),eq("J06.9"),eq("stable"),eq(1))).thenReturn(m);MockMvc mvc=MockMvcBuilders.standaloneSetup(new MedicalRecordController(use)).build();mvc.perform(post("/api/v1/medical-records/{id}/prescriptions",id).contentType("application/json").content("{\"medication\":\"Rx\"}")).andExpect(status().isOk());mvc.perform(post("/api/v1/medical-records/{id}/close-encounter",id).contentType("application/json").content("{\"cie10\":\"J06.9\",\"evolution\":\"stable\",\"disabilityDays\":1}")).andExpect(status().isOk());}

 @Test void timelineAndProductivityRoutesInvokeUseCase() throws Exception {MedicalRecordUseCase use=mock(MedicalRecordUseCase.class);UUID id=UUID.randomUUID();when(use.timeline(id)).thenReturn(List.of());when(use.productivity(id)).thenReturn(Map.of("closedEncounters",0));MockMvc mvc=MockMvcBuilders.standaloneSetup(new MedicalRecordController(use)).build();mvc.perform(get("/api/v1/medical-records/patient/{id}/clinical-timeline",id)).andExpect(status().isOk());mvc.perform(get("/api/v1/medical-records/doctor/{id}/productivity-report",id)).andExpect(status().isOk()).andExpect(jsonPath("$.closedEncounters").value(0));}
}
